static func gfx_auto_tier() -> int:
	if ChikFeat.native_hd():
		return 2

if _phone:
	vp.scaling_3d_scale = minf(vp.scaling_3d_scale, 0.5 if low else 0.7)
elif ChikFeat.native_hd():
	# FULL HD: the 3D drawn 1080 pixels tall (the whole screen on one that is not taller). A
	# Pro Max is 1290 pixels tall, so its native size would cost 40% more for detail the eye
	# cannot find at arm's length.
	var ws: = DisplayServer.window_get_size()
	var fhd: = clampf(1080.0 / float(maxi(1, mini(ws.x, ws.y))), 0.5, 1.0)
	vp.scaling_3d_scale = minf(vp.scaling_3d_scale, fhd)
